'use strict';

// U1: the vendored classifier (vendor/classifier/) is generated by marrow-install
// scripts/classifier-generate.js and pinned. Any byte drift from the pinned source commit fails.
const test = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, '..');
const VENDOR = path.join(ROOT, 'vendor', 'classifier');
const { CLASSIFIER_PIN } = require('../dist/seatbelt/classifier-pin.js');

const sha256 = (data) => crypto.createHash('sha256').update(data).digest('hex');
const gitBlob = (data) => crypto.createHash('sha1').update(`blob ${data.length}\0`).update(data).digest('hex');
const MODULES = ['classifier.js', 'policy-baseline.js', 'redact.js', 'shell-parse.js'];

function driftProblems(readVendor) {
  const problems = [];
  const manifestRaw = readVendor('MANIFEST.json');
  if (sha256(manifestRaw) !== CLASSIFIER_PIN.manifest_sha256) problems.push('MANIFEST.json: sha256 differs from pin');
  const manifest = JSON.parse(manifestRaw.toString('utf8'));
  if (manifest.contract !== CLASSIFIER_PIN.contract) problems.push('contract differs');
  if (manifest.source_commit !== CLASSIFIER_PIN.source_commit) problems.push('source_commit differs from pin');
  if (manifest.source_repo !== CLASSIFIER_PIN.source_repo || manifest.source_dir !== CLASSIFIER_PIN.source_dir) problems.push('source repo/dir differs');
  const lines = [];
  for (const name of MODULES) {
    const data = readVendor(name);
    const pin = CLASSIFIER_PIN.files[name];
    if (sha256(data) !== pin.sha256) problems.push(`${name}: sha256 differs from pin`);
    if (gitBlob(data) !== pin.git_blob) problems.push(`${name}: git blob differs from ${CLASSIFIER_PIN.source_commit}`);
    if (!manifest.files[name] || manifest.files[name].sha256 !== sha256(data)) problems.push(`${name}: manifest hash mismatch`);
    lines.push(`${sha256(data)}  ${name}\n`);
  }
  const bundle = sha256(lines.join(''));
  if (bundle !== CLASSIFIER_PIN.bundle_sha256 || bundle !== manifest.bundle_sha256) problems.push('bundle_sha256 differs from pin');
  const extra = fs.readdirSync(VENDOR).filter((f) => f !== 'MANIFEST.json' && !MODULES.includes(f));
  if (extra.length) problems.push(`unexpected vendored files: ${extra.join(',')}`);
  return problems;
}

test('vendored classifier matches the pinned source commit byte-for-byte', () => {
  assert.deepEqual(driftProblems((name) => fs.readFileSync(path.join(VENDOR, name))), []);
  assert.equal(CLASSIFIER_PIN.source_commit, '8954813607eca211476ba612f4599a21e1a49946');
  assert.equal(CLASSIFIER_PIN.contract, 'marrow.classifier.v1');
});

test('a one-byte change to any vendored file or the manifest is detected', () => {
  for (const target of [...MODULES, 'MANIFEST.json']) {
    const read = (name) => {
      const data = Buffer.from(fs.readFileSync(path.join(VENDOR, name)));
      if (name === target) data[data.length - 2] ^= 1;
      return data;
    };
    let problems;
    try { problems = driftProblems(read); } catch (error) { problems = [`parse: ${error.message}`]; }
    assert.ok(problems.length > 0, `drift in ${target} not detected`);
  }
});

test('the mapper loads the vendored modules, and the package ships them', () => {
  const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8'));
  assert.ok(pkg.files.includes('vendor/classifier'), 'package.json files must include vendor/classifier');
  const mapper = fs.readFileSync(path.join(ROOT, 'dist', 'seatbelt', 'mapper.js'), 'utf8');
  for (const m of ['shell-parse.js', 'policy-baseline.js', 'classifier.js']) assert.ok(mapper.includes(`../../vendor/classifier/${m}`), m);
  // U5: only the pre-action hook uses the seatbelt, and only through a lazy require inside a try (a
  // module that fails to load is a stop, never a crash of the hook); no static import anywhere.
  for (const f of fs.readdirSync(path.join(ROOT, 'src'))) {
    if (!f.endsWith('.ts')) continue;
    const text = fs.readFileSync(path.join(ROOT, 'src', f), 'utf8');
    assert.ok(!/^import [^;]*['"]\.\/seatbelt\//m.test(text), `${f} must not import the seatbelt statically`);
    if (f === 'normalized-action.ts') {
      // M2: the exact-action key reads the device salt through one lazy require inside a try (a module that fails to
      // load is a nonce, so the held action is asked again; never a crash, never an unsalted key).
      assert.equal((text.match(/seatbelt\//g) || []).length, 2, `${f} uses the seatbelt only for the device salt`);
      assert.match(text, /try \{\n\s*salt = \(require\('\.\/seatbelt\/record'\) as typeof import\('\.\/seatbelt\/record'\)\)\.deviceSalt\(\);\n\s*\} catch \{/, `${f}: lazy, inside a try`);
    } else if (f !== 'hook-pre-action.ts') assert.ok(!/seatbelt\//.test(text), `${f} must not use the seatbelt`);
  }
});
